def f(N: int, Q: int, A: List[int], B: List[int]) -> int:
    # Find the number of unique elements in A
    uniqueA = set(A)
    uniqueA = {el for el in uniqueA if el <= N}
    uniqueA = {el for el in uniqueA if el >= 2}
    countA = len(uniqueA)

    # Find the number of unique elements in B
    uniqueB = set(B)
    uniqueB = {el for el in uniqueB if el <= N}
    uniqueB = {el for el in uniqueB if el >= 2}
    countB = len(uniqueB)

    # If countA and countB are the same, return their count 
    if countA == countB:
        return countA

    # If countA is less than countB, return countA
    elif countA < countB:
        return countA

    # If countA is more than countB, return countB
    else:
        return countB
```

